import ipaddress,re
def repair_hosts(text,hostname,address):
    if not isinstance(text,str) or "\x00" in text or len(text)>65536:raise ValueError("invalid hosts input")
    if not isinstance(hostname,str) or len(hostname)>253 or not hostname:raise ValueError("invalid hostname")
    if any(not re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?",label) for label in hostname.split(".")):raise ValueError("invalid hostname")
    try:approved=ipaddress.IPv4Address(address)
    except (ValueError,TypeError):raise ValueError("approved IPv4 loopback required")
    if not approved.is_loopback:raise ValueError("private exercise requires approved loopback")
    found=False
    for line in text.splitlines():
        fields=line.split("#",1)[0].split()
        if len(fields)>1 and hostname.casefold() in [name.casefold().rstrip(".") for name in fields[1:]]:
            try:current=ipaddress.ip_address(fields[0])
            except ValueError:raise ValueError("existing hostname has malformed address")
            if current!=approved:raise ValueError("existing hostname mapping conflicts; review required")
            found=True
    if found:return text
    return text+("" if not text or text.endswith("\n") else "\n")+str(approved)+" "+hostname+"\n"
```

